/* ---------- dates ---------- */
function toD(s){const [y,m,d]=s.split("-").map(Number);return new Date(Date.UTC(y,m-1,d));}
function iso(d){return d.toISOString().slice(0,10);}
function addDays(s,n){const d=toD(s);d.setUTCDate(d.getUTCDate()+n);return iso(d);}
const WD=["อา.","จ.","อ.","พ.","พฤ.","ศ.","ส."], MO=["ม.ค.","ก.พ.","มี.ค.","เม.ย.","พ.ค.","มิ.ย.","ก.ค.","ส.ค.","ก.ย.","ต.ค.","พ.ย.","ธ.ค."];
function isWE(s){const w=toD(s).getUTCDay();return w===0||w===6;}
function thDate(s,y){const d=toD(s);return WD[d.getUTCDay()]+" "+d.getUTCDate()+" "+MO[d.getUTCMonth()]+(y?" "+(d.getUTCFullYear()+543):"");}

/* ---------- state ---------- */
const LS="ru-exam-plan.web.v2";
let S=defaults();
function adopt(o){if(!o)return; try{o=JSON.parse(JSON.stringify(o));}catch(e){return;} if(o.v===2){S=Object.assign(defaults(),o);} else if(o.v===1){const d=defaults(); d.status=o.status||d.status; d.diff=o.diff||d.diff; S=d;}}
try{adopt(JSON.parse(localStorage.getItem(LS)||localStorage.getItem("ru-exam-plan.v1")||"null"));}catch(e){}
let dbRef=null, saveTimer=null;
const $=id=>document.getElementById(id);
function setSave(t){$("saveState").textContent=t;}
function persist(){
  S.updatedAt=Date.now();
  try{localStorage.setItem(LS,JSON.stringify(S));}catch(e){}
  clearTimeout(saveTimer);
  if(dbRef){saveTimer=setTimeout(()=>{dbRef.set(JSON.parse(JSON.stringify(S))).catch(()=>toast("บันทึกลงบัญชีไม่สำเร็จ ข้อมูลยังอยู่ในเครื่องนี้"));},700);}
  else setSave("บันทึกในเบราว์เซอร์นี้");
}
let fbAuth=null,fbUser=null;
function acctUI(){const li=$("btnLogin"),lo=$("btnLogout"),who=$("acctName");if(!li)return;
  if(!fbAuth){li.hidden=true;lo.hidden=true;who.textContent="ยังไม่ได้เปิดระบบล็อกอิน · บันทึกในเครื่องนี้";return;}
  li.hidden=!!fbUser;lo.hidden=!fbUser;who.textContent=fbUser?(fbUser.displayName||fbUser.email||"บัญชีของคุณ"):"ยังไม่ได้เข้าสู่ระบบ · บันทึกในเครื่องนี้";}
async function connect(){
  const cfg=window.FIREBASE_CONFIG;
  if(!window.firebase||!cfg||!cfg.apiKey){acctUI();return;}
  try{firebase.initializeApp(cfg);fbAuth=firebase.auth();const fs=firebase.firestore();
    $("btnLogin").onclick=()=>fbAuth.signInWithPopup(new firebase.auth.GoogleAuthProvider()).catch(e=>toast("เข้าสู่ระบบไม่สำเร็จ: "+(e&&e.code||"")));
    $("btnLogout").onclick=async()=>{await fbAuth.signOut();try{localStorage.removeItem(LS);}catch(e){}S=defaults();render();toast("ออกจากระบบแล้ว");};
    fbAuth.onAuthStateChanged(async u=>{fbUser=u;acctUI();
      if(!u){dbRef=null;return;}
      dbRef=fs.collection("users").doc(u.uid);
      try{const snap=await dbRef.get();
        if(snap.exists){const o=snap.data();adopt(o);try{localStorage.setItem(LS,JSON.stringify(S));}catch(e){}render();}
        else persist();
        setSave("");}catch(e){toast("โหลดแผนจากบัญชีไม่ได้");}});
  }catch(e){fbAuth=null;acctUI();}
}

/* ---------- model ---------- */
function allTerms(){return BUILTIN.concat(S.uploaded||[]);}
function groups(){const m={};allTerms().forEach(t=>{(m[t.group]=m[t.group]||[]).push(t);});
  return Object.keys(m).sort().map(g=>({id:g,terms:m[g].sort((a,b)=>(a.kind==="resit")-(b.kind==="resit"))}));}
function groupName(g){const [y,s]=g.split("-");return s==="3"?"ฤดูร้อน "+y:"ภาค "+s+"/"+y;}
function curGroup(){const gs=groups();return gs.find(g=>g.id===S.group)||gs.find(g=>g.id===S.lastGroup)||gs[gs.length-1];}
function termById(id){return allTerms().find(t=>t.id===id);}
function isOther(code){return /^[A-Z]+\d0\d\d$/.test(code)||NONLAW.has(code);}
function info(code){const c=CAT[code];const g=c?c[3]:0;return c?{full:c[0],th:c[1],en:c[2],req:g===1,grp:g,plan:PLAN[code]||""}:{full:"",th:"",en:(DB[code]||[])[1]||"",req:false,grp:0,plan:""};}
const GRPL={1:"บังคับ",2:"เลือกกฎหมาย",0:"ไม่อยู่ในหลักสูตร 2563"};
function entry(t,code){if(!t)return null;t._m=t._m||Object.fromEntries(t.entries.map(e=>[e[0],{code:e[0],cr:e[1],date:e[2],p:e[3]}]));return t._m[code]||null;}
function gsel(g){if(!S.sel[g.id])S.sel[g.id]={};return S.sel[g.id];}
function crOf(g,code){for(const t of g.terms){const e=entry(t,code);if(e)return e.cr;}return CAT[code]?0:0;}
function sitting(g,t){const sel=gsel(g),out=[];for(const c in sel){if(sel[c]===t.id||(sel[c]==="resit"&&t.kind==="resit")){const e=entry(t,c);if(e)out.push(e);}}return out;}
function resitTerm(g){return g.terms.find(t=>t.kind==="resit")||null;}
function toResit(g,code){const rt=resitTerm(g);const s=gsel(g);const e=rt&&entry(rt,code);s[code]=e?rt.id:"resit";persist();render();toast(e?fmtCode(code)+" ย้ายไปสอบซ่อม "+thDate(e.date)+" คาบ "+e.p:fmtCode(code)+" ตั้งเป็นไปสอบซ่อมแล้ว พอเพิ่มตารางสอบซ่อม วิชานี้จะขึ้นในปฏิทินรอบซ่อมเอง");}
function blockedSet(t){return new Set(S.blocked[t.id]||[]);}
function unavailable(t,date){if(!date)return false;if(blockedSet(t).has(date))return true;return !!S.weekend[t.id]&&!isWE(date);}
function kindLabel(t){return t.kind==="resit"?"รอบซ่อม":"รอบปกติ";}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function fmtCode(c){return c.replace(/^([A-Z]+)(\d+)$/,"$1 $2");}
const canHover=window.matchMedia&&window.matchMedia("(hover: hover) and (pointer: fine)").matches;



/* ---------- grades & summary ---------- */
const GP={"A":4,"B+":3.5,"B":3,"C+":2.5,"C":2,"D+":1.5,"D":1,"F":0};
const PASSG=new Set(["A","B+","B","C+","C","D+","D"]);
// วิชาศึกษาทั่วไปและเลือกเสรีตามไฟล์ตารางวิชา
const EXTRA={
 "HIS1001":["อารยธรรมตะวันตก","Western Civilization",3,"ge"],"PSY1001":["จิตวิทยาทั่วไป","General Psychology",3,"ge"],
 "POL1100":["รัฐศาสตร์ทั่วไป","Introduction to Political Science",3,"ge"],"RAM1000":["ความรู้คู่คุณธรรม","Knowledge and Morality",3,"ge"],
 "BIO2202":["ชีวิตและระบบนิเวศวิทยา","Life and System Ecology",3,"ge"],"SCI1003":["วิทยาศาสตร์พื้นฐาน","Basic Science",3,"ge"],
 "THA1001":["ลักษณะและการใช้ภาษาไทย","Structure of Thai and Its Usage",3,"ge"],"THA1003":["การเตรียมเพื่อพูดและเขียน","Preparation for Speech and Writing",3,"ge"],
 "ENG1001":["ภาษาอังกฤษพื้นฐาน","Basic English",3,"ge"],"ENG1002":["ประโยคและคำศัพท์ภาษาอังกฤษ","English Sentence and Vocabulary",3,"ge"]};
function stOf(code){const g=S.grades&&S.grades[code];if(g&&g.ok&&PASSG.has(g.g))return "passed";return S.status[code];}
function ex(code){const c=S.custom&&S.custom[code];return c||EXTRA[code]||null;}
function crAny(code){const x=ex(code);if(x)return x[2];for(const t of allTerms()){const e=entry(t,code);if(e)return e.cr;}return DB[code]?DB[code][0]:0;}
function catOf(code){const x=ex(code);if(x)return x[3];const i=info(code);if(i.grp===1)return "req";if(/^LAW/.test(code)&&!isOther(code))return "lawel";return "free";}
function nameOf(code){const x=ex(code);if(x)return {th:x[0],en:x[1]||(DB[code]||[])[1]||""};const i=info(code);return {th:i.full||i.th,en:i.en||(DB[code]||[])[1]||""};}
function planOf(code){const out=[];groups().forEach(g=>{const v=(S.sel[g.id]||{})[code];if(!v)return;
  if(v==="skip"){out.push({g,label:groupName(g.id)+" · ลงไว้ ไม่สอบ"});return;}
  if(v==="resit"){const rt=resitTerm(g),e=rt&&entry(rt,code);out.push({g,t:rt,e,label:groupName(g.id)+" · ไปสอบซ่อม"+(e&&e.date?" "+thDate(e.date)+" คาบ "+e.p:" (รอตาราง)")});return;}const t=termById(v),e=entry(t,code);
  out.push({g,t,e,label:groupName(g.id)+" · "+(t?kindLabel(t):"")+(e&&e.date?" "+thDate(e.date)+" คาบ "+e.p:"")});});return out;}
