function setSitting(g,code,val){const s=gsel(g);if(val===null)delete s[code];else s[code]=val;persist();render();}
function quickAdd(g){
  const box=document.createElement("div");box.className="qa";
  const dlId="qa_"+g.id;const seen=new Set();let opts="";
  g.terms.forEach(t=>t.entries.forEach(e=>{const c=e[0];if(seen.has(c)||isOther(c))return;seen.add(c);const i=info(c);
    opts+='<option value="'+c+'">'+esc(c+" "+(i.th||i.en||"")+(i.grp===1?" (บังคับ)":" (เลือก)")+" · "+(e[2]?thDate(e[2])+" "+e[3]:"คณะจัดสอบเอง")+(t.kind==="resit"?" ซ่อม":""))+'</option>';}));
  box.innerHTML='<label class="qal" for="qaIn">ค้นหาวิชาแล้วใส่ในตาราง</label><input id="qaIn" list="'+dlId+'" autocomplete="off" placeholder="พิมพ์รหัสหรือชื่อ เช่น 2102 หรือ หนี้"><datalist id="'+dlId+'">'+opts+'</datalist><button type="button" class="btn pri" id="qaGo">ใส่ในตาราง</button><span class="muted qam" id="qaMsg"></span>';
  const go=()=>{const v=box.querySelector("#qaIn").value;let code=(v.match(/[A-Za-z]{2,4}\s*\d{4}/)||[""])[0].toUpperCase().replace(/\s+/g,"");
    if(!code){const q=v.trim().toLowerCase();if(q){const hit=[...seen].find(c=>{const i=info(c);return (c+" "+i.th+" "+i.full+" "+i.en).toLowerCase().includes(q);});if(hit)code=hit;}}
    if(!code){box.querySelector("#qaMsg").textContent="ไม่พบวิชาที่ค้นหา";return;}
    if(!seen.has(code)){box.querySelector("#qaMsg").textContent=fmtCode(code)+" ไม่มีในตารางสอบของเทอมนี้";return;}
    const sel=gsel(g);if(sel[code]&&sel[code]!=="skip"){const t=sel[code]==="resit"?resitTerm(g):termById(sel[code]),e=t&&entry(t,code);box.querySelector("#qaMsg").textContent=fmtCode(code)+" อยู่ในแผนแล้ว"+(e&&e.date?" ("+thDate(e.date)+" "+e.p+")":"");return;}
    const taken={};g.terms.forEach(t=>sitting(g,t).forEach(e=>{if(e.date)taken[t.id+"|"+e.date+"|"+e.p]=1;}));
    const cands=g.terms.map(t=>({t,e:entry(t,code)})).filter(o=>o.e);
    const ok=o=>!unavailable(o.t,o.e.date)&&!gBusy(o.e.date,o.e.p)&&!taken[o.t.id+"|"+o.e.date+"|"+o.e.p];
    const best=cands.find(o=>ok(o)&&o.t.kind!=="resit")||cands.find(ok)||cands[0];
    sel[code]=best.t.id;persist();
    picker=null;render();
    toast("ใส่ "+fmtCode(code)+" แล้ว"+(best.e.date?" · "+kindLabel(best.t)+" "+thDate(best.e.date)+" คาบ "+best.e.p:"")+(ok(best)?"":" (ชนหรือตรงวันไม่ว่าง ดูคำเตือน)"));};
  box.querySelector("#qaGo").onclick=go;box.querySelector("#qaIn").onkeydown=e=>{if(e.key==="Enter"){e.preventDefault();go();}};
  return box;
}
