function analyze(g){
  const sel=gsel(g),W=[],cap=S.cap[g.id]||0;
  const codes=Object.keys(sel), cr=codes.reduce((a,c)=>a+crOf(g,c),0);
  const n={h:0,m:0,e:0,u:0};codes.forEach(c=>n[S.diff[c]||"u"]++);
  if(cap&&cr>cap)W.push(["bad","หน่วยกิตรวมทั้งเทอม "+cr+" เกินเพดาน "+cap+" (รอบปกติกับรอบซ่อมนับรวมกัน)"]);
  let exams=0,lastDay=null,firstDay=null,bestStreak=0,badCount=0;
  g.terms.forEach(t=>{
    const L=sitting(g,t),tag=kindLabel(t)+": ";exams+=L.filter(e=>e.date).length;
    const by={};L.forEach(e=>{if(e.date)(by[e.date+"|"+e.p]=by[e.date+"|"+e.p]||[]).push(e);});
    Object.values(by).filter(l=>l.length>1).forEach(l=>W.push(["bad",tag+"สอบชนกัน "+thDate(l[0].date)+" คาบ "+l[0].p+": "+l.map(e=>fmtCode(e.code)).join(" กับ "),{term:t.id,date:l[0].date,p:l[0].p}]));
    L.filter(e=>unavailable(t,e.date)).forEach(e=>W.push(["bad",tag+fmtCode(e.code)+" สอบ "+thDate(e.date)+" คาบ "+e.p+" ซึ่งเป็นวันที่ตั้งไว้ว่าไม่ว่าง",{term:t.id,date:e.date,p:e.p}]));
    L.forEach(e=>{const gb=gBusy(e.date,e.p);if(gb&&!unavailable(t,e.date))W.push(["bad",tag+fmtCode(e.code)+" สอบ "+thDate(e.date)+" คาบ "+e.p+" ชนกับนัดใน Google Calendar: "+(gb.all?"ทั้งวัน ":gb.s+"–"+gb.e+" ")+gb.t,{term:t.id,date:e.date,p:e.p}]);});
    const days={};L.forEach(e=>{if(e.date)(days[e.date]=days[e.date]||[]).push(e);});
    const dl=Object.keys(days).sort();
    if(dl.length){if(!firstDay||dl[0]<firstDay)firstDay=dl[0];if(!lastDay||dl[dl.length-1]>lastDay)lastDay=dl[dl.length-1];}
    dl.filter(d=>new Set(days[d].map(e=>e.p)).size>1).forEach(d=>{const hh=days[d].filter(e=>S.diff[e.code]==="h").length;
      W.push([hh>=2?"bad":"mid",tag+"สอบเช้าและบ่าย "+thDate(d)+": "+days[d].map(e=>fmtCode(e.code)).join(" + ")+(hh>=2?" (ยากทั้งคู่)":""),{term:t.id,date:d}]);});
    let run=[];const runs=[];dl.forEach((d,i)=>{if(i&&addDays(dl[i-1],1)===d)run.push(d);else{if(run.length)runs.push(run);run=[d];}});if(run.length)runs.push(run);
    runs.forEach(r=>{bestStreak=Math.max(bestStreak,r.length);if(r.length>=3)W.push(["mid",tag+"สอบติดกัน "+r.length+" วัน ("+thDate(r[0])+" – "+thDate(r[r.length-1])+")"]);});
    for(let i=1;i<dl.length;i++)if(addDays(dl[i-1],1)===dl[i]&&days[dl[i-1]].some(e=>S.diff[e.code]==="h")&&days[dl[i]].some(e=>S.diff[e.code]==="h"))W.push(["mid",tag+"วิชายากสอบวันติดกัน "+thDate(dl[i-1])+" และ "+thDate(dl[i])]);
  });
  const pres=codes.filter(c=>sel[c]==="resit"&&!(resitTerm(g)&&entry(resitTerm(g),c)));
  if(pres.length)W.push(["mid","ตั้งเป็นไปสอบซ่อม แต่ยังไม่มีตารางสอบซ่อม: "+pres.map(fmtCode).join(", ")+" (นับหน่วยกิตแล้ว)"]);
  const skip=codes.filter(c=>sel[c]==="skip");
  if(skip.length)W.push(["mid","ลงทะเบียนไว้แต่ยังไม่ได้เลือกรอบสอบ: "+skip.map(fmtCode).join(", ")+" (นับหน่วยกิตแล้ว)"]);
  codes.filter(c=>stOf(c)==="passed").forEach(c=>W.push(["mid",fmtCode(c)+" ตั้งสถานะว่าผ่านแล้ว แต่ยังอยู่ในแผน"]));
  if(n.h>3)W.push(["mid","มีวิชายาก "+n.h+" ตัวในเทอมเดียว ลองสลับบางตัวเป็นวิชากลางหรือง่าย"]);
  orderWarnings(g).forEach(w=>W.push(w));
  badCount=W.filter(w=>w[0]==="bad").length;
  if(!W.length&&codes.length)W.push(["ok","ไม่พบวิชาชนกันหรือวันสอบที่ไม่ว่าง"]);
  if(!codes.length)W.push(["ok","ยังไม่ได้เลือกวิชาในเทอมนี้ แตะช่องในตารางหรือเลือกจากรายวิชา"]);
  return {codes,cr,cap,n,W,exams,firstDay,lastDay,bestStreak,badCount};
}

