   '<div class="stat"><span class="k">ยาก · กลาง · ง่าย</span><span class="mix"><b style="color:var(--hard)">'+a.n.h+'</b><b style="color:var(--med)">'+a.n.m+'</b><b style="color:var(--easy)">'+a.n.e+"</b>"+(a.n.u?'<small class="muted">ไม่ระบุ '+a.n.u+"</small>":"")+"</span></div>"+
   '<div class="stat"><span class="k">วิชา · นัดสอบ</span><span class="v">'+a.codes.length+" <small>วิชา</small> "+a.exams+" <small>นัด</small></span></div>"+
   '<div class="stat"><span class="k">สอบวันแรก → วันสุดท้าย</span><span class="v" style="font-size:1rem">'+(a.firstDay?thDate(a.firstDay)+" → "+thDate(a.lastDay):"–")+"</span></div>"+
   '<button type="button" class="stat statbtn" id="probStat"><span class="k">ปัญหาที่ต้องแก้'+(a.badCount?' · แตะเพื่อดู':'')+'</span><span class="v'+(a.badCount?" bad":"")+'">'+a.badCount+' <small>'+(a.badCount?esc((a.W.find(w=>w[0]==="bad")||["",""])[1].replace(/^รอบ(ปกติ|ซ่อม): /,"")):"ไม่มี")+'</small></span></button>'+
   '<div class="stat"><span class="k">สอบติดกันยาวสุด</span><span class="v">'+a.bestStreak+" <small>วัน</small></span></div>";
  const ul=$("warns");ul.innerHTML="";a.W.forEach(w=>{const li=document.createElement("li");li.className=w[0];li.innerHTML='<span class="dot"></span><span class="wt">'+esc(w[1])+"</span>";
    if(w[2]){const b=document.createElement("button");b.type="button";b.className="wgo";b.textContent="ดูในปฏิทิน";b.onclick=()=>goIssue(w[2]);li.appendChild(b);}ul.appendChild(li);});
  $("probStat").onclick=()=>{const first=a.W.find(w=>w[0]==="bad"&&w[2]);if(first)goIssue(first[2]);else{$("warnTitle").scrollIntoView({behavior:"smooth",block:"start"});}};
