function renderList(g){
  const q=$("q").value.trim().toLowerCase(),fReq=$("fReq").checked,fPassed=$("fPassed").checked,fFree=$("fFree").checked,fOther=$("fOther").checked;
  const sel=gsel(g),codes=new Set();g.terms.forEach(t=>t.entries.forEach(e=>codes.add(e[0])));Object.keys(sel).forEach(c=>codes.add(c));
  const taken={};g.terms.forEach(t=>sitting(g,t).forEach(e=>{if(e.date){const k=t.id+"|"+e.date+"|"+e.p;(taken[k]=taken[k]||[]).push(e.code);}}));
  const optsFor=code=>g.terms.map(t=>{const e=entry(t,code);if(!e)return null;const k=t.id+"|"+e.date+"|"+e.p;
    return {t,e,off:unavailable(t,e.date)||!!gBusy(e.date,e.p),busy:gBusy(e.date,e.p),clash:(e.date&&taken[k]||[]).filter(c=>c!==code)};}).filter(Boolean);
  let rows=[...codes].map(code=>({code,opts:optsFor(code)}));
  rows=rows.filter(r=>{const i=info(r.code),on=!!sel[r.code];
    if(!fOther&&isOther(r.code)&&!on)return false;
    if(fReq&&!i.grp)return false;
    if(fPassed&&stOf(r.code)==="passed"&&!on)return false;
    if(fFree&&!on&&!r.opts.some(o=>!o.off&&!o.clash.length&&o.e.date))return false;
    if(q){const hay=(r.code+" "+r.code.replace(/[A-Z]+/,"")+" "+i.full+" "+i.th+" "+i.en).toLowerCase();if(!hay.includes(q))return false;}
    return true;});
  const firstDate=r=>{const o=r.opts[0];return o&&o.e.date?o.e.date+o.e.p:"9";};
  rows.sort((a,b)=>((!!sel[b.code])-(!!sel[a.code]))||firstDate(a).localeCompare(firstDate(b))||a.code.localeCompare(b.code));
  $("listCount").textContent=rows.length+" วิชา";$("slotf").hidden=true;
  const L=$("list");L.innerHTML="";
  if(!rows.length){L.innerHTML='<div class="row"><span></span><span class="muted">ไม่มีวิชาตรงกับตัวกรอง</span><span></span></div>';return;}
  const DL={h:"ยาก",m:"กลาง",e:"ง่าย","":"ความยาก ?"},SL={todo:"ยังไม่ผ่าน",pending:"รอผล/ค้างซ่อม",passed:"ผ่านแล้ว"};
  rows.forEach(r=>{
    const i=info(r.code),cur=sel[r.code],on=!!cur,st=stOf(r.code)||"todo",df=S.diff[r.code]||"";
    const allBad=r.opts.length&&r.opts.every(o=>o.off||o.clash.length);
    const row=document.createElement("div");row.className="row"+(on?" on":"")+((!on&&(allBad||st==="passed"))?" dim":"");
    const cb=document.createElement("input");cb.type="checkbox";cb.checked=on;cb.id="cb_"+r.code;cb.setAttribute("aria-label","เลือก "+r.code);
    cb.onchange=()=>{if(!cb.checked){setSitting(g,r.code,null);return;}
      const best=r.opts.find(o=>!o.off&&!o.clash.length&&o.t.kind!=="resit")||r.opts.find(o=>!o.off&&!o.clash.length)||r.opts[0];
      setSitting(g,r.code,best?best.t.id:"skip");};
    const tt=document.createElement("label");tt.className="t";tt.htmlFor=cb.id;
    tt.innerHTML='<span class="c">'+esc(fmtCode(r.code))+'</span> <span class="nm">'+esc(i.th||"")+"</span>"+(i.full&&i.full!==i.th?'<div class="full">'+esc(i.full)+"</div>":"")+'<div class="en">'+esc(i.en?i.en+" · ":"")+GRPL[i.grp]+(i.plan?" · แผนการเรียน ปี "+i.plan:"")+((DB[r.code]||[])[2]?" · ต้องผ่าน "+esc(DB[r.code][2])+" ก่อน":"")+"</div>";
    const meta=document.createElement("div");meta.className="meta";
    const cr=r.opts[0]?r.opts[0].e.cr:0;
    const crp=document.createElement("span");crp.className="pill cr";crp.textContent=cr+" นก.";
    const dp=document.createElement("button");dp.type="button";dp.className="pill "+df;dp.textContent=DL[df];dp.title="แตะเพื่อเปลี่ยนความยาก";
    dp.onclick=()=>{const o=["h","m","e",""];const nx=o[(o.indexOf(df)+1)%4];if(nx)S.diff[r.code]=nx;else delete S.diff[r.code];persist();render();};
    const sp=document.createElement("button");sp.type="button";sp.className="pill "+(st==="todo"?"":st);sp.textContent=SL[st];sp.title="แตะเพื่อเปลี่ยนสถานะ";
    sp.onclick=()=>{const o=["todo","pending","passed"];const nx=o[(o.indexOf(st)+1)%3];if(nx==="todo")delete S.status[r.code];else S.status[r.code]=nx;persist();render();};
    const np=document.createElement("button");np.type="button";np.className="pill"+((S.notes||{})[r.code]?" pending":"");np.textContent=noteOpen.has(r.code)?"ปิดโน้ต":((S.notes||{})[r.code]?"โน้ต ✎":"+ โน้ต");
    np.onclick=()=>{noteOpen.has(r.code)?noteOpen.delete(r.code):noteOpen.add(r.code);renderList(g);};
    meta.append(crp,dp,sp,np);
    const opts=document.createElement("div");opts.className="opts";
    if(on){const seg=document.createElement("div");seg.className="seg";seg.setAttribute("role","group");seg.setAttribute("aria-label","เลือกรอบสอบ "+r.code);
      r.opts.forEach(o=>{const b=document.createElement("button");b.type="button";b.setAttribute("aria-pressed",String(cur===o.t.id));
        b.textContent=(o.t.kind==="resit"?"ซ่อม ":"ปกติ ")+(o.e.date?thDate(o.e.date)+" "+o.e.p:"คณะจัดสอบ")+(o.busy?" ติดนัด":o.off?" ⚠":"")+(o.clash.length?" ชน":"");
        b.title=o.clash.length?"ชนกับ "+o.clash.map(fmtCode).join(", "):o.busy?"ติดนัด "+o.busy.t:o.off?"วันไม่ว่าง":"";
        b.onclick=()=>setSitting(g,r.code,o.t.id);seg.appendChild(b);});
      if(!r.opts.some(o=>o.t.kind==="resit")&&g.id.split("-")[1]!=="3"){const rs=document.createElement("button");rs.type="button";rs.setAttribute("aria-pressed",String(cur==="resit"));rs.textContent="ไปสอบซ่อม (รอตาราง)";rs.onclick=()=>setSitting(g,r.code,"resit");seg.appendChild(rs);}
      const sk=document.createElement("button");sk.type="button";sk.setAttribute("aria-pressed",String(cur==="skip"));sk.textContent="ลงไว้ ไม่สอบ";sk.onclick=()=>setSitting(g,r.code,"skip");seg.appendChild(sk);
      opts.appendChild(seg);}
    else{const w=document.createElement("div");w.className="when";w.style.gridColumn="auto";
      w.innerHTML=r.opts.map(o=>"<span>"+(o.t.kind==="resit"?"ซ่อม: ":"ปกติ: ")+(o.e.date?esc(thDate(o.e.date,true))+" คาบ "+o.e.p:"คณะจัดสอบเอง")+(o.busy?' <span class="bad">ติดนัด: '+esc(o.busy.t)+"</span>":o.off?' <span class="bad">วันไม่ว่าง</span>':"")+(o.clash.length?' <span class="bad">ชนกับ '+esc(o.clash.map(fmtCode).join(", "))+"</span>":"")+"</span>").join("")||"<span>ไม่มีในตารางสอบเทอมนี้</span>";
      opts.appendChild(w);}
    row.append(cb,tt,meta,opts);
    const nt=(S.notes||{})[r.code]||"";
    if(noteOpen.has(r.code)){const ta=document.createElement("textarea");ta.className="note-ta";ta.id="note_"+r.code;ta.value=nt;ta.placeholder="ขอบเขตข้อสอบ อาจารย์ หนังสือ ลิงก์ หรือรีวิว";ta.setAttribute("aria-label","โน้ต "+r.code);
      ta.oninput=()=>{S.notes=S.notes||{};if(ta.value.trim())S.notes[r.code]=ta.value;else delete S.notes[r.code];clearTimeout(ta._t);ta._t=setTimeout(persist,600);};row.appendChild(ta);}
    else if(nt){const pv=document.createElement("div");pv.className="note-pv";pv.textContent="📝 "+nt.split("\n")[0];row.appendChild(pv);}
    if(canHover){const o=r.opts.find(o=>o.e.date);if(o){const gk=o.t.id+"|"+o.e.date+"|"+o.e.p;
      row.addEventListener("mouseenter",()=>{ghost=gk;markGhost();});row.addEventListener("mouseleave",()=>{ghost=null;markGhost();});}}
    L.appendChild(row);});
}
function markGhost(){document.querySelectorAll(".cell.ghost").forEach(c=>c.classList.remove("ghost"));if(!ghost)return;
  const c=document.querySelector('.cell[data-k="'+ghost+'"]');if(c)c.classList.add("ghost");}

/* ---------- export ---------- */
function toast(m){const el=$("toast");el.textContent=m;el.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>el.hidden=true,2600);}
function title(code){const i=info(code);return "สอบ "+fmtCode(code)+(i.en?" - "+i.en:"")+(i.th?" ("+i.th+")":"");}
function examsOf(g){const out=[];g.terms.forEach(t=>sitting(g,t).forEach(e=>{if(e.date)out.push({t,e});}));return out.sort((a,b)=>(a.e.date+a.e.p).localeCompare(b.e.date+b.e.p));}
function csvFor(g){
  const q=v=>'"'+String(v).replace(/"/g,'""')+'"';
  const fmtT=(h,m)=>{const ap=h>=12?"PM":"AM";return (((h+11)%12)+1)+":"+String(m).padStart(2,"0")+" "+ap;};
  const lines=[["Subject","Start Date","Start Time","End Date","End Time","All Day Event","Description","Location"].join(",")];
  examsOf(g).forEach(({t,e})=>{const [y,mo,d]=e.date.split("-"),ds=mo+"/"+d+"/"+y,sh=e.p==="A"?9:14,sm=e.p==="A"?30:0,end=sh*60+sm+(e.cr>=3?150:120);
    lines.push([q(title(e.code)),ds,fmtT(sh,sm),ds,fmtT(Math.floor(end/60),end%60),"False",q(kindLabel(t)+" ภาค "+t.name+" · คาบ "+e.p+" · "+e.cr+" หน่วยกิต"),q("มหาวิทยาลัยรามคำแหง")].join(","));});
  return "﻿"+lines.join("\r\n")+"\r\n";
}
let downloads=null;
function copyText(s,msg){const fb=()=>{const ta=document.createElement("textarea");ta.value=s;document.body.appendChild(ta);ta.select();try{document.execCommand("copy");toast(msg);}catch(e){toast("คัดลอกไม่ได้");}ta.remove();};
  if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(s).then(()=>toast(msg),fb);else fb();}
function icsFor(g){
  const pad=n=>String(n).padStart(2,"0");
  const utc=(d,hm)=>{const [y,m,dd]=d.split("-").map(Number),[h,mi]=hm.split(":").map(Number);const t=new Date(Date.UTC(y,m-1,dd,h-7,mi));return t.getUTCFullYear()+pad(t.getUTCMonth()+1)+pad(t.getUTCDate())+"T"+pad(t.getUTCHours())+pad(t.getUTCMinutes())+"00Z";};
  const esc2=s=>String(s).replace(/\\/g,"\\\\").replace(/;/g,"\;").replace(/,/g,"\\,").replace(/\n/g,"\\n");
  const L=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//RU Exam Dates//TH","CALSCALE:GREGORIAN","METHOD:PUBLISH"];
  examsOf(g).forEach(({t,e})=>{const iv=indivOf(e.code,e.date);let s,en;
    if(iv&&iv.start){s=iv.start;en=iv.end;}else{const [sh,sm]=SLOT[e.p][0].split(":").map(Number),x=sh*60+sm+(e.cr>=3?150:120);s=SLOT[e.p][0];en=pad(Math.floor(x/60))+":"+pad(x%60);}
    L.push("BEGIN:VEVENT","UID:"+e.code+"-"+e.date+"@ru-exam-dates","DTSTAMP:"+utc(todayISO(),"07:00"),"DTSTART:"+utc(e.date,s),"DTEND:"+utc(e.date,en),
      "SUMMARY:"+esc2(title(e.code)),"DESCRIPTION:"+esc2(kindLabel(t)+" ภาค "+t.name+" · คาบ "+e.p+" · "+e.cr+" หน่วยกิต"+(iv?"\n"+indivDesc(iv):"")),
      "LOCATION:"+esc2(iv&&iv.room?iv.room+(iv.campus?" "+iv.campus:"")+", มหาวิทยาลัยรามคำแหง":"มหาวิทยาลัยรามคำแหง"),
      "BEGIN:VALARM","ACTION:DISPLAY","DESCRIPTION:"+esc2(title(e.code)),"TRIGGER:-P1D","END:VALARM","BEGIN:VALARM","ACTION:DISPLAY","DESCRIPTION:"+esc2(title(e.code)),"TRIGGER:-PT2H","END:VALARM","END:VEVENT");});
  L.push("END:VCALENDAR");return L.join("\r\n")+"\r\n";
}
function saveFile(name,data,type){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},500);}
$("btnCsv").onclick=()=>{const g=curGroup();if(!examsOf(g).length){toast("ยังไม่มีวิชาที่มีวันสอบในเทอมนี้");return;}
  saveFile("ตารางสอบ_"+groupName(g.id).replace(/[\s\/.]+/g,"_")+".ics",icsFor(g),"text/calendar");toast("ดาวน์โหลดไฟล์ .ics แล้ว นำเข้าได้ที่ Google Calendar → ตั้งค่า → นำเข้า");};
$("btnCopy").onclick=()=>{const g=curGroup(),a=analyze(g),sel=gsel(g);
  const lines=["แผนสอบ "+groupName(g.id)+" ("+a.cr+" หน่วยกิต)"].concat(examsOf(g).map(({t,e})=>"- "+kindLabel(t)+" "+thDate(e.date)+" คาบ "+e.p+": "+fmtCode(e.code)+" "+(info(e.code).th||"")+" ("+e.cr+")"))
    .concat(Object.keys(sel).filter(c=>sel[c]==="skip").map(c=>"- ลงไว้ ไม่สอบ: "+fmtCode(c)+" "+(info(c).th||"")));
  copyText(lines.join("\n"),"คัดลอกรายการแล้ว");};
